ass=[('A-FINAL','Source domain','external trust','pending historical outcomes','S02 S06 S08 S10','Correct finality and non-equivocation of admitted canonical history'),('A-EXEC','Local contracts','external trust','all actions','S01 S04 S05 S08','Correct atomic local EVM execution and exact supported token behavior'),('A-CRYPTO','Proof implementer','crypto idealization','signature creation through verification','S03 S06 S10','Ideal signatures, commitments and proof soundness with structured bindings'),('A-HOLD','Issuer governance','stakeholder choice','prepare through terminal application','S04 S07 S08 L02','Admitted token semantics preserve pending obligations'),('A-RECOVERY','Chain/service operators','admissible environment','eventual suffix','L01 L02 L03 L04','Eventually required dependencies remain operational'),('A-FAIR','Scheduler/operators','admissible environment','eventual suffix','L01 L02 L03 L04','Weak fairness for each continuously enabled per-trade/per-phase recovery action'),('A-DATA','Evidence store','enforceable local control','capture through application/retention','L02 S13','Durable evidence or reconstructible finalized history remains available'),('A-SUBMIT','Custody/submission owner','enforceable local control','decision/application','L01 L02 L03','At least one already authorized submission path can progress'),('A-OPAQUE','Crypto abstraction','crypto idealization','privacy executions','P-NI P-Binding','Fresh opaque names preserve equality/linkability; no computational privacy proof'),('A-POLICY','Institution/compliance','stakeholder choice','disclosure/audit','P-Access P-Scope','Selected observer policy and audit scope are explicitly configured')]
